//-- POWER

void sx128x_rfpower_calc(const int8_t power_dbm, int8_t* sx_power, int8_t* actual_power_dbm)
{
    if (power_dbm >= POWER_20_DBM) {
        *sx_power = 1;
        *actual_power_dbm = 20;
    } else if (power_dbm >= POWER_17_DBM) {
        *sx_power = -3;
        *actual_power_dbm = 17;
    } else if (power_dbm >= POWER_14_DBM) {
        *sx_power = -6;
        *actual_power_dbm = 14;
    } else {
        *sx_power = -10;
        *actual_power_dbm = 10;
    }
}

